      mac === true ?
      event?.metaKey === true && event?.ctrlKey !== true :
      event?.ctrlKey === true && event?.metaKey !== true;
      if (!platformModifier) return 0;
      if (event?.key === 'ArrowDown') return 1;
      if (event?.key === 'ArrowUp') return -1;
