      let boundary = active;
      while (boundary < rows.length - 1 && searchEverywhereResultGroupKey(rows[boundary + 1]) === group) boundary += 1;
      if (boundary === rows.length - 1) return null;
      const nextGroup = searchEverywhereResultGroupKey(rows[boundary + 1]);
