      const left = Math.max(4, Math.min(Number(x) || 0, viewportWidth - width - 4));
      const preferredTop = (Number(y) || 0) + 4;
      const top = preferredTop + height > viewportHeight ? (Number(y) || 0) - height : preferredTop;
      return { left, top: Math.max(4, top) };
