    function changeGroupMenu({ t, position, groupBy, onApplyChangeGroupBy }) {
      return {
        x: position.x,
        y: position.y,
        title: t('editor.groupByMenu'),
        items: ['flat', 'module', 'directory'].map((mode) => ({
          id: `groupBy:${mode}`,
          label: t(`editor.groupBy_${mode}`),
          shortcut: groupBy === mode ? '✓' : '',
          restoreFocus: false,
          run: () => onApplyChangeGroupBy(mode)
        }))
      };
    }

    function changesViewOptionsMenu({
      t,
      position,
      groupBy,
      onApplyChangeGroupBy
    }) {
      const groupMenu = changeGroupMenu({
        t,
        position,
        groupBy,
        onApplyChangeGroupBy
      });
      return {
        owner: 'changes-view-options',
        x: position.x,
        y: position.y,
        title: t('editor.viewOptions'),
        items: [
        {
          id: 'groupBy',
          label: t('editor.groupByMenu'),
          items: groupMenu.items
        }]

      };
    }

    function commitOptionsMenu({
      t,
      position,
      fetchBusy,
      updateBusy,
      commitBusy,
      stageAllAvailable,
      groupBy,
      onApplyChangeGroupBy,
      onFetch,
      onUpdate,
      onApplyPatchFile,
      onApplyPatchClipboard,
      onStageAll,
      onStash,
      onShelve
    }) {
      const groupMenu = changeGroupMenu({
        t,
        position,
        groupBy,
        onApplyChangeGroupBy
      });
      return {
        owner: 'commit-options',
        x: position.x,
        y: position.y,
        title: t('editor.commitOptions'),
        items: [
        {
          id: 'fetch',
          label: fetchBusy ? t('editor.fetchBusy') : t('editor.fetchRemote'),
          disabled: fetchBusy,
          run: onFetch
        },
        {
          id: 'update',
          label: updateBusy ? t('editor.updateBusy') : t('editor.updateProject'),
          disabled: updateBusy,
          run: onUpdate
        },
        null,
        {
          id: 'applyPatchFile',
          label: t('editor.applyPatch'),
          disabled: commitBusy,
          run: onApplyPatchFile
        },
        {
          id: 'applyPatchClipboard',
          label: t('editor.applyPatchFromClipboard'),
          disabled: commitBusy,
          run: onApplyPatchClipboard
        },
        null,
        {
          id: 'stageAll',
          label: t('editor.stageAll'),
          disabled: commitBusy || !stageAllAvailable,
          run: onStageAll
        },
        null,
        {
          id: 'stash',
          label: t('editor.stash'),
          run: onStash
        },
        {
          id: 'shelve',
          label: t('editor.shelve'),
          run: onShelve
        },
        null,
        {
          id: 'groupBy',
          label: t('editor.groupByMenu'),
          items: groupMenu.items
        }]

      };
    }

